def style():
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.titlesize':13,'axes.labelsize':10,'axes.spines.top':False,'axes.spines.right':False,'axes.edgecolor':'#c4ced2','axes.labelcolor':INK,'text.color':INK,'xtick.color':INK,'ytick.color':INK,'figure.facecolor':'white','axes.facecolor':'white','savefig.facecolor':'white','svg.fonttype':'none','grid.color':'#e6ecef'})

def save(fig,name):
    fig.savefig(ROOT/'figures'/f'{name}.png',dpi=170,bbox_inches='tight')
    fig.savefig(ROOT/'figures'/f'{name}.svg',bbox_inches='tight')
    plt.close(fig)

def finish(fig,title,subtitle=None):
    fig.suptitle(title,x=.04,ha='left',fontsize=20,fontweight='bold')
    if subtitle:fig.text(.04,-.025,subtitle,ha='left',fontsize=9,color='#586e77')

def read(name):return pd.read_csv(ROOT/'results'/name,sep=';')

