def html_shell(title,subtitle,body):
    return f'''<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>body{{margin:0;background:#f5f7f8;color:#183440;font:16px system-ui,sans-serif}}main{{max-width:1280px;margin:auto;padding:36px 28px}}h1{{font-size:34px;margin:0 0 10px;letter-spacing:-1px}}p{{line-height:1.6;color:#49616d}}nav{{display:flex;gap:20px;margin:20px 0}}a{{color:#147d86}}section{{background:white;border:1px solid #dce6ea;border-radius:12px;padding:20px;margin:20px 0}}select,input{{font:inherit;padding:10px;border:1px solid #bbced5;border-radius:6px;max-width:100%}}.controls label{{max-width:100%;min-width:0}}select,input{{box-sizing:border-box}}.controls{{display:flex;gap:16px;flex-wrap:wrap;align-items:center}}.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}}.card{{background:#edf3f5;padding:16px;border-radius:8px}}.value{{font-size:26px;font-weight:650}}.label{{font-size:13px;color:#526a75}}#components{{height:370px}}#sensitivity{{height:390px}}#distribution{{height:290px}}footer{{font-size:13px;color:#526a75;line-height:1.6}}@media(max-width:700px){{main{{padding:20px 12px}}.cards{{grid-template-columns:1fr 1fr}}}}</style><script>{get_plotlyjs()}</script><main><h1>{title}</h1><p>{subtitle}</p><nav><a href="index.html">Přehled</a><a href="candidates.html">Žebříčky</a><a href="candidate_detail.html">Detail kandidáta</a></nav>{body}<footer>Zdroj pozorovaných dat: ČSÚ, dodané exporty 2026. Modelové údaje jsou vlastní odvozená analýza, nikoli oficiální měření osobních křížků. Vše funguje bez připojení. Metodika: <a href="../methodology.md">methodology.md</a>.</footer></main></html>'''

def make_interactive():
    H,obs,city=load_data();c=read('candidate_estimates.csv');party=read('party_estimates.csv');sens=read('prior_sensitivity.csv');pc=read('candidate_precinct_estimates.csv');cs=read('candidate_sensitivity.csv');out=load_fit('reference',H)
    fig=go.Figure();groups=[('Top 30 celkem',c.nlargest(30,'personal_median'))]+[(SHORT[s],c[c.party_id==s+1].sort_values('personal_median',ascending=False)) for s in range(8)]
    for g,(label,d) in enumerate(groups):
        hover=np.column_stack((d.votes,d.position,d.rigorous_min_personal_marks_sum_precincts,d.rank_q025,d.rank_q975))
        fig.add_trace(go.Scatter(x=d.personal_median.tolist(),y=d.name.tolist(),mode='markers',name='Medián + 95% CI',visible=g==0,marker={'color':TEAL,'size':8},error_x={'type':'data','symmetric':False,'array':(d.personal_q975-d.personal_median).tolist(),'arrayminus':(d.personal_median-d.personal_q025).tolist(),'color':TEAL,'thickness':1.5},customdata=hover.tolist(),hovertemplate='<b>%{y}</b><br>Modelový medián: %{x:.0f}<br>Pozorováno: %{customdata[0]:.0f}<br>Pozice: %{customdata[1]:.0f}<br>Rigorózní bodové minimum: %{customdata[2]:.0f}<br>95% interval pořadí: %{customdata[3]:.0f}–%{customdata[4]:.0f}<extra></extra>'))
        fig.add_trace(go.Scatter(x=d.rigorous_min_personal_marks_sum_precincts.tolist(),y=d.name.tolist(),mode='markers',name='Bodová dolní mez',visible=g==0,marker={'color':'#384d57','size':8,'symbol':'line-ns'},hovertemplate='%{y}<br>Jisté minimum: %{x}<extra></extra>'))
    buttons=[]
